-- TASK-060 AC-CNT-04 reserve batch R6.
--
-- Closes the PM.MET release-reserve cells with 37 original source-backed Y1
-- questions: 18 bilish and 19 mulohaza. Items are grounded in the
-- source-backed M16 Informatika o'qitish metodikasi lessons.
--
-- Idempotent by source_reference; source lessons are resolved through active
-- construct links, preferring non-empty source-backed lesson bodies.

begin;

do $$
declare
 item jsonb;
 v_subject uuid;
 v_construct uuid;
 v_group text;
 v_lesson uuid;
 v_question uuid;
 v_option uuid;
 v_i int;
 v_correct int;
begin
 for item in select * from jsonb_array_elements('[{"exp":"Metodik tizim maqsadni aniqlovchi ‘Nima uchun o‘qitiladi?’ savolidan boshlanadi.","ref":"reserve-2026:T060-R6-PMMET-B01","stem":"Informatika o‘qitish metodikasining tayanch savollaridan biri qaysi?","correct":0,"options":["Nima uchun o‘qitiladi?","Faqat nechta kompyuter bor?","Faqat dars qaysi xonada?","Faqat o‘quvchi yoshi nechada?"],"cognitive":"bilish","construct":"PM.MET.01","difficulty":2},{"exp":"Metodik tizim maqsad, mazmun, metod, tashkiliy shakl va vositalarning o‘zaro bog‘langan majmuasidir.","ref":"reserve-2026:T060-R6-PMMET-B02","stem":"Metodik tizimning asosiy tarkibiga qaysi elementlar kiradi?","correct":0,"options":["Maqsad, mazmun, metodlar, shakllar va vositalar","Faqat darslik va daftar","Faqat kompyuter va printer","Faqat baho va davomat"],"cognitive":"bilish","construct":"PM.MET.01","difficulty":2},{"exp":"Bu savol o‘qitiladigan mazmun va tushunchalar tizimini belgilaydi.","ref":"reserve-2026:T060-R6-PMMET-B03","stem":"‘Nima o‘qitiladi?’ savoli metodik tizimning qaysi qismiga tegishli?","correct":0,"options":["Mazmunga","Faqat baholashga","Faqat xavfsizlikka","Faqat jihozga"],"cognitive":"bilish","construct":"PM.MET.01","difficulty":2},{"exp":"Qanday o‘qitish metodik qarorlar majmuasini anglatadi.","ref":"reserve-2026:T060-R6-PMMET-B04","stem":"‘Qanday o‘qitiladi?’ savoli nimani tanlash bilan bog‘liq?","correct":0,"options":["Metod, shakl, vosita va o‘quv faoliyatini","Faqat mavzu nomini","Faqat sinf raqamini","Faqat daftar turini"],"cognitive":"bilish","construct":"PM.MET.01","difficulty":2},{"exp":"Bir elementdagi o‘zgarish boshqa elementlarga ham ta’sir qiladi.","ref":"reserve-2026:T060-R6-PMMET-B05","stem":"Metodik tizimdagi elementlar qanday munosabatda?","correct":0,"options":["O‘zaro bog‘langan","Butunlay mustaqil","Faqat maqsad boshqalardan mustaqil","Faqat vosita muhim"],"cognitive":"bilish","construct":"PM.MET.01","difficulty":2},{"exp":"Metodik tizim maqsadga mos ravishda faoliyat va baholashni ham o‘zgartirishni talab qiladi.","ref":"reserve-2026:T060-R6-PMMET-B06","stem":"Amaliy kompetensiya maqsadi qo‘yilsa, qaysi o‘zgarish mantiqan kerak?","correct":0,"options":["Topshiriq, vaqt, ish shakli va baholashni amaliy faoliyatga moslashtirish","Faqat ta’rif yodlashni ko‘paytirish","Amaliyotni olib tashlash","Faqat slayd rangini o‘zgartirish"],"cognitive":"bilish","construct":"PM.MET.01","difficulty":2},{"exp":"Metod ta’lim maqsadiga erishish uchun o‘zaro faoliyatni tashkil etish yo‘lidir.","ref":"reserve-2026:T060-R6-PMMET-B07","stem":"O‘qitish metodi nimaga eng yaqin ta’riflanadi?","correct":0,"options":["O‘qituvchi va o‘quvchining maqsadga yo‘naltirilgan o‘zaro faoliyatini tashkil etish yo‘li","Faqat texnik qurilma","Faqat dars jadvali","Faqat sinf xonasi"],"cognitive":"bilish","construct":"PM.MET.02","difficulty":2},{"exp":"Usul metodning konkret bajarilish elementi bo‘lishi mumkin.","ref":"reserve-2026:T060-R6-PMMET-B08","stem":"O‘qitish usuli nima bo‘lishi mumkin?","correct":0,"options":["Metodning aniq vaziyatdagi tarkibiy elementi yoki bajarilish ko‘rinishi","Har doim alohida fan","Faqat baholash turi","Faqat apparat vositasi"],"cognitive":"bilish","construct":"PM.MET.02","difficulty":2},{"exp":"Interaktiv doska texnik vosita; undan qanday foydalanish metodik qarordir.","ref":"reserve-2026:T060-R6-PMMET-B09","stem":"Interaktiv doska metodmi yoki vositami?","correct":0,"options":["Vosita","Har doim metod","Faqat baholash","Faqat mazmun"],"cognitive":"bilish","construct":"PM.MET.02","difficulty":2},{"exp":"Ko‘nikma o‘quvchining amaliy harakati orqali shakllanadi.","ref":"reserve-2026:T060-R6-PMMET-B10","stem":"Amaliy mashq qaysi holatda ayniqsa muhim?","correct":0,"options":["Ko‘nikma shakllantirishda","Faqat nazariy ta’rif yodlashda","Faqat davomatda","Faqat tadbirda"],"cognitive":"bilish","construct":"PM.MET.02","difficulty":2},{"exp":"Interfaollik mazmunli o‘zaro ta’sir va fikr almashishga tayanadi.","ref":"reserve-2026:T060-R6-PMMET-B11","stem":"Interfaol metodning asosiy belgisi qaysi?","correct":0,"options":["Faol fikr almashish va o‘zaro ta’sir","Faqat guruhga bo‘lish","Faqat o‘qituvchi monologi","Faqat kompyuter yoqish"],"cognitive":"bilish","construct":"PM.MET.02","difficulty":2},{"exp":"Reproduktiv faoliyat tayyor namuna/usulni takroran qo‘llashga tayanadi.","ref":"reserve-2026:T060-R6-PMMET-B12","stem":"Reproduktiv faoliyat nimaga yaqin?","correct":0,"options":["Berilgan namuna yoki usulni qayta bajarishga","Yangi muammoni mustaqil tadqiq etishga har doim","Faqat baholashga","Faqat jihoz tanlashga"],"cognitive":"bilish","construct":"PM.MET.02","difficulty":2},{"exp":"Pedagogik qaror maqsadga xizmat qilishi kerak, shuning uchun maqsad aniqligi tayanch mezondir.","ref":"reserve-2026:T060-R6-PMMET-B13","stem":"Ta’limiy qarorni tahlil qilishda birinchi mezonlardan biri qaysi?","correct":0,"options":["Dars maqsadining aniqligi","Slayd rangining yoqimliligi","O‘qituvchining kiyimi","Sinf devori rangi"],"cognitive":"bilish","construct":"PM.MET.03","difficulty":2},{"exp":"Natija dalili baholashning maqsad va faoliyat bilan bog‘liqligini ko‘rsatadi.","ref":"reserve-2026:T060-R6-PMMET-B14","stem":"Dars tahlilida ‘o‘quvchi natijasi qanday dalil bilan tekshirildi?’ savoli nimaga xizmat qiladi?","correct":0,"options":["Baholash dalilining maqsadga mosligini tekshirishga","Faqat davomatni aniqlashga","Faqat jihozni tekshirishga","Faqat uy vazifasini yozishga"],"cognitive":"bilish","construct":"PM.MET.03","difficulty":2},{"exp":"Metodik tahlil dalil va mezonlarga asoslanadi.","ref":"reserve-2026:T060-R6-PMMET-B15","stem":"Dars tahlili faqat ‘yoqdi/yoqmadi’ga tayanishi to‘g‘rimi?","correct":0,"options":["Yo‘q, mezon va dalillarga tayanishi kerak","Ha, shaxsiy taassurot yetarli","Faqat o‘quvchi soni muhim","Faqat dars davomiyligi muhim"],"cognitive":"bilish","construct":"PM.MET.03","difficulty":2},{"exp":"O‘z-o‘zini tahlil qilish dars qarorlari va keyingi takomillashtirishni tushunishga yordam beradi.","ref":"reserve-2026:T060-R6-PMMET-B16","stem":"O‘qituvchining o‘z-o‘zini tahlili dars tahlilida nima uchun muhim?","correct":0,"options":["Qarorlar sababi va o‘qituvchining refleksiyasini tushunish uchun","Faqat maqtov uchun","Faqat hisobotni uzaytirish uchun","Keraksiz"],"cognitive":"bilish","construct":"PM.MET.03","difficulty":2},{"exp":"Metodik tahlil ta’lim jarayoni elementlarining maqsadga muvofiqligini ko‘radi.","ref":"reserve-2026:T060-R6-PMMET-B17","stem":"Metodik tahlil nimani baholaydi?","correct":0,"options":["Maqsad, mazmun, metod, faoliyat va natija o‘rtasidagi moslikni","Faqat sinf xonasi haroratini","Faqat o‘quvchi kiyimini","Faqat darslik narxini"],"cognitive":"bilish","construct":"PM.MET.03","difficulty":2},{"exp":"Qaror ‘zamonaviy’ ko‘rinishi emas, vaziyatga asoslangan mosligi bilan baholanadi.","ref":"reserve-2026:T060-R6-PMMET-B18","stem":"Eng yaxshi pedagogik qaror qanday tanlanadi?","correct":0,"options":["Mavjud vaziyat, maqsad va o‘quvchi ehtiyojiga eng asosli mosligi bo‘yicha","Eng yangi nomga ega bo‘lgani uchun","Eng ko‘p texnika ishlatgani uchun","Eng uzoq davom etgani uchun"],"cognitive":"bilish","construct":"PM.MET.03","difficulty":2},{"exp":"Algoritmik fikrlash maqsadi faol muammo tahlili va algoritm yaratishni talab qiladi.","ref":"reserve-2026:T060-R6-PMMET-M01","stem":"Maqsad algoritmik fikrlashni rivojlantirish, lekin dars faqat ta’riflarni yodlashdan iborat. Eng asosli metodik xulosa?","correct":0,"options":["Faoliyat maqsadga yetarli mos emas; tahlil, algoritm tuzish va tekshirish kerak","Ta’rif yodlashning o‘zi barcha maqsadni yopadi","Maqsadni olib tashlash kerak","Faqat slaydni ko‘paytirish yetarli"],"cognitive":"mulohaza","construct":"PM.MET.01","difficulty":4},{"exp":"Baholash kutilgan amaliy natijani o‘lchashi kerak.","ref":"reserve-2026:T060-R6-PMMET-M02","stem":"Dars maqsadi amaliy ko‘nikma, lekin baholash faqat nazariy terminlarni eslashga qaratilgan. Nima buzilgan?","correct":0,"options":["Metodik tizimning maqsad-baholash mosligi","Faqat jihoz tanlovi","Faqat dars davomiyligi","Faqat fan nomi"],"cognitive":"mulohaza","construct":"PM.MET.01","difficulty":4},{"exp":"Vosita metodik tizimda maqsadga xizmat qilishi kerak, aksincha emas.","ref":"reserve-2026:T060-R6-PMMET-M03","stem":"Yangi vosita paydo bo‘ldi va o‘qituvchi barcha darsni unga moslab o‘zgartirmoqchi. Eng to‘g‘ri yondashuv?","correct":0,"options":["Avval maqsad va mazmunga vosita qanday xizmat qilishini baholash","Vosita yangi bo‘lsa har doim qo‘llash","Maqsadni vositaga moslab butunlay almashtirish","Baholashni olib tashlash"],"cognitive":"mulohaza","construct":"PM.MET.01","difficulty":4},{"exp":"O‘quvchi tayyorgarligi metod, shakl va vositalarni moslashtirishni talab qilishi mumkin.","ref":"reserve-2026:T060-R6-PMMET-M04","stem":"Ikki sinfning tayyorgarligi turlicha. Bir xil maqsad qolsa ham metodik tizimda nima o‘zgarishi mumkin?","correct":0,"options":["Metod, yordam, vaqt va faoliyat shakli","Hech narsa","Faqat fan nomi","Faqat jurnal"],"cognitive":"mulohaza","construct":"PM.MET.01","difficulty":4},{"exp":"Metodik tizim barcha elementlarning o‘zaro mosligini talab qiladi.","ref":"reserve-2026:T060-R6-PMMET-M05","stem":"Maqsad aniq, mazmun mos, ammo o‘quvchiga amaliy faoliyat uchun kompyuter va vaqt ajratilmagan. Nima uchun tizim to‘liq emas?","correct":0,"options":["Vosita va tashkiliy shartlar maqsadga moslashtirilmagan","Mazmun bo‘lsa qolganlari shart emas","Faqat baholash yetarli","Kompyuter hech qachon kerak emas"],"cognitive":"mulohaza","construct":"PM.MET.01","difficulty":4},{"exp":"Natija metodik tizim elementlari o‘rtasidagi moslik orqali tahlil qilinadi.","ref":"reserve-2026:T060-R6-PMMET-M06","stem":"Darsda o‘quvchi natijasi kutilganidan past. Metodik tahlil faqat ‘mavzu qiyin’ degan xulosada to‘xtadi. Nima yetishmayapti?","correct":0,"options":["Maqsad, mazmun, metod, faoliyat, vosita va baholash orasidagi bog‘lanishni tahlil qilish","Faqat dars nomini almashtirish","Faqat bahoni ko‘tarish","Faqat qo‘shimcha uy vazifa"],"cognitive":"mulohaza","construct":"PM.MET.01","difficulty":4},{"exp":"Ko‘nikma uchun o‘quvchi mustaqil amaliy harakat bajarishi kerak.","ref":"reserve-2026:T060-R6-PMMET-M07","stem":"O‘qituvchi yangi dastur interfeysini 20 daqiqa namoyish qildi, lekin o‘quvchilar o‘zlari ishlamadi. Nega ko‘nikma sust shakllandi?","correct":0,"options":["Namoyish tayanch berdi, ammo amaliy mashq yetishmadi","Namoyish har doim ko‘nikmani to‘liq shakllantiradi","Kompyuterda ishlash shart emas","Faqat test yetarli"],"cognitive":"mulohaza","construct":"PM.MET.02","difficulty":4},{"exp":"Interfaollik tashkiliy shaklning o‘zi emas, mazmunli o‘zaro ta’sirdir.","ref":"reserve-2026:T060-R6-PMMET-M08","stem":"Guruhga bo‘lingan o‘quvchilar faqat yonma-yon o‘tirib individual ishladi. Bu interfaol metodmi?","correct":0,"options":["To‘liq emas; vazifa o‘zaro fikr almashish va hamkorlikni talab qilishi kerak","Ha, guruhga bo‘lishning o‘zi interfaollik","Interfaollikda muloqot bo‘lmaydi","Faqat o‘qituvchi gapirishi kerak"],"cognitive":"mulohaza","construct":"PM.MET.02","difficulty":4},{"exp":"Metod reproduktiv tayanchdan faol tahlil va mustaqil faoliyatga o‘tadi.","ref":"reserve-2026:T060-R6-PMMET-M09","stem":"Dasturlashni o‘rgatishda o‘qituvchi tayyor kodni ko‘rsatadi, keyin o‘quvchi xatoni topib tuzatadi va o‘z variantini yozadi. Nega bu yaxshiroq?","correct":0,"options":["Namuna tayanch beradi, keyingi faoliyat esa tahlil va mustaqil qo‘llashni talab qiladi","Tayyor kodni ko‘rishning o‘zi yetarli","Xato topish dasturlashga aloqasiz","O‘quvchi kod yozmasligi kerak"],"cognitive":"mulohaza","construct":"PM.MET.02","difficulty":4},{"exp":"Vosita va metod farqlanadi; qurilma interfaol faoliyatni kafolatlamaydi.","ref":"reserve-2026:T060-R6-PMMET-M10","stem":"Interaktiv doska ishlatilgani uchun dars avtomatik interfaol bo‘ladimi?","correct":0,"options":["Yo‘q, interfaollik o‘quvchi faoliyati va o‘zaro ta’sirga bog‘liq","Ha, qurilma bo‘lsa yetarli","Faqat internet tezligi muhim","Interaktiv doska metodning o‘zi"],"cognitive":"mulohaza","construct":"PM.MET.02","difficulty":4},{"exp":"Muammoli ta’limning markazi tayyor javobdan oldingi fikrlash va izlanishdir.","ref":"reserve-2026:T060-R6-PMMET-M11","stem":"Muammoli vaziyat berildi, lekin o‘qituvchi darhol tayyor javobni aytdi. Muammoli metodning qaysi imkoniyati yo‘qoldi?","correct":0,"options":["O‘quvchining muammoni tahlil qilib yechim izlash faoliyati","Faqat yozuv tezligi","Faqat davomat","Faqat baho"],"cognitive":"mulohaza","construct":"PM.MET.02","difficulty":4},{"exp":"Metod tanlovi vazifaga bog‘liq, turli metodlar bir-birini to‘ldirishi mumkin.","ref":"reserve-2026:T060-R6-PMMET-M12","stem":"Bir darsda ma’ruza, namoyish va amaliy mashq birgalikda ishlatildi. Bu noto‘g‘rimi?","correct":0,"options":["Yo‘q, maqsadga xizmat qilsa metodlarni uyg‘unlashtirish mumkin","Ha, faqat bitta metod bo‘lishi shart","Amaliy mashq bilan tushuntirish birga bo‘lmaydi","Namoyish metod emas"],"cognitive":"mulohaza","construct":"PM.MET.02","difficulty":4},{"exp":"Muammo o‘quvchi faoliyati va bosqichli yordam nisbatida bo‘lishi mumkin.","ref":"reserve-2026:T060-R6-PMMET-M13","stem":"O‘qituvchi yangi Python mavzusini 35 daqiqa doskada yozdi, 5 daqiqa mustaqil ish berdi; ko‘pchilik boshlay olmadi. Eng asosli tavsiya?","correct":0,"options":["Namuna, boshqariladigan mashq va mustaqil faoliyat nisbatini qayta rejalash","O‘quvchilarni sust deb baholash","Ma’ruzani 40 daqiqaga uzaytirish","Mustaqil ishni butunlay olib tashlash"],"cognitive":"mulohaza","construct":"PM.MET.03","difficulty":4},{"exp":"Tahlil maqsad va natija bilan bog‘langan dalilga asoslanishi kerak.","ref":"reserve-2026:T060-R6-PMMET-M14","stem":"Dars kuzatuvchisi ‘menga metod yoqmadi’ dedi, lekin maqsad, natija yoki dalilni ko‘rsatmadi. Bu tahlilning kamchiligi?","correct":0,"options":["Subyektiv fikrga tayanib, mezon va dalil yetishmaydi","Tahlil mukammal","Metodik tahlilda dalil kerak emas","Faqat metod nomi yetarli"],"cognitive":"mulohaza","construct":"PM.MET.03","difficulty":4},{"exp":"Dalil muammoning aniq manbasini ko‘rsatmoqda; tavsiya ham shu manbaga yo‘naltiriladi.","ref":"reserve-2026:T060-R6-PMMET-M15","stem":"O‘qituvchi o‘z-o‘zini tahlilda vaqt yetmaganini aytdi; kuzatuv esa o‘tishlarda 12 daqiqa yo‘qotilganini ko‘rsatdi. Eng asosli tavsiya?","correct":0,"options":["O‘tish bosqichlari va material tayyorligini rejalab, vaqt boshqaruvini sinash","Faqat darsni qisqartirish","O‘quvchilarni ayblash","Vaqtni o‘lchamaslik"],"cognitive":"mulohaza","construct":"PM.MET.03","difficulty":4},{"exp":"Baholash kutilgan natijaning asosiy komponentlarini dalillashi kerak.","ref":"reserve-2026:T060-R6-PMMET-M16","stem":"Dars maqsadi hamkorlikda muammo yechish, lekin baholash faqat individual termin testidan iborat. Tahlil nima deydi?","correct":0,"options":["Baholash maqsadning hamkorlik va muammo yechish qismini o‘lchamayapti","Test bo‘lsa har qanday maqsad o‘lchanadi","Baholash maqsadga bog‘liq emas","Hamkorlikni baholab bo‘lmaydi"],"cognitive":"mulohaza","construct":"PM.MET.03","difficulty":4},{"exp":"Metodik qaror turli o‘quvchi ehtiyojlariga ta’siri bo‘yicha ham tahlil qilinadi.","ref":"reserve-2026:T060-R6-PMMET-M17","stem":"Yangi metoddan keyin natija yaxshilandi, lekin faqat kuchli o‘quvchilarda. Qaysi tahlil to‘liqroq?","correct":0,"options":["Natijani guruhlar kesimida ko‘rib, individual farqlar va qo‘llab-quvvatlashni tahlil qilish","Umumiy o‘rtacha oshgan bo‘lsa boshqa dalil kerak emas","Zaif o‘quvchilarni hisobga olmaslik","Metodni har doim o‘zgartirmaslik"],"cognitive":"mulohaza","construct":"PM.MET.03","difficulty":4},{"exp":"Natija dalili bo‘lmasa maqsadga erishilganini asosli baholab bo‘lmaydi.","ref":"reserve-2026:T060-R6-PMMET-M18","stem":"Darsda maqsad aniq, faoliyat mos, lekin o‘quvchi natijasi tekshirilmagan. Dars samarasi haqida qat’iy xulosa qilish mumkinmi?","correct":0,"options":["Yo‘q, natija bo‘yicha dalil yetishmaydi","Ha, maqsad yozilgani yetarli","Ha, o‘qituvchi ko‘p gapirgan","Faqat darslik yetarli"],"cognitive":"mulohaza","construct":"PM.MET.03","difficulty":4},{"exp":"Professional dars tahlili shaxsga emas, kuzatiladigan faoliyat va takomillashtirishga yo‘naltiriladi.","ref":"reserve-2026:T060-R6-PMMET-M19","stem":"Kuzatuvda o‘qituvchi xatoga yo‘l qo‘ydi. Tahlilchi uni shaxs sifatida tanqid qildi, lekin aniq dars qarorini ko‘rsatmadi. Qanday yaxshilash kerak?","correct":0,"options":["Shaxsiy bahodan voz kechib, kuzatilgan qaror, ta’sir va aniq tavsiyani muhokama qilish","Tanqidni kuchaytirish","Faqat omma oldida aytish","Dalilni yashirish"],"cognitive":"mulohaza","construct":"PM.MET.03","difficulty":4}]'::jsonb)
 loop
  if exists(select 1 from public.questions where source_reference=item->>'ref') then
   continue;
  end if;

  select c.id,c.subject_id,c.group_code
    into v_construct,v_subject,v_group
    from public.constructs c
   where c.code=item->>'construct'
     and c.is_active;

  if v_construct is null then
   raise exception 'TASK-060 R6 construct not found: %',item->>'construct';
  end if;

  select l.id into v_lesson
    from public.lesson_constructs lc
    join public.lessons l on l.id=lc.lesson_id
   where lc.construct_id=v_construct
     and l.status='published'::public.content_status
   order by case when coalesce(l.body_mdx,'')<>'' then 0 else 1 end,l.order_idx,l.id
   limit 1;

  if v_lesson is null then
   raise exception 'TASK-060 R6 source lesson not found: %',item->>'construct';
  end if;

  v_question:=gen_random_uuid();
  insert into public.questions(
    id,subject_id,construct_id,group_code,format,cognitive,difficulty,stem_md,
    assets,is_generated,status,author_id,source_reference,source_lesson_id
  ) values (
    v_question,v_subject,v_construct,v_group,
    'Y1'::public.question_format,
    (item->>'cognitive')::public.cognitive_level,
    (item->>'difficulty')::int,
    item->>'stem',
    '[]'::jsonb,
    false,
    'published'::public.content_status,
    null,
    item->>'ref',
    v_lesson
  );

  v_correct:=(item->>'correct')::int;
  for v_i in 0..3 loop
   v_option:=gen_random_uuid();
   insert into public.question_options(id,question_id,content_md,order_idx)
   values(v_option,v_question,item->'options'->>v_i,v_i);
   if v_i=v_correct then
    insert into public.question_keys(question_id,payload,explanation_md)
    values(v_question,jsonb_build_object('correct_option_id',v_option),item->>'exp');
   end if;
  end loop;
 end loop;
end
$$;

commit;
